#!/bin/bash
# 읽기 전용: 재빌드된 nvblox_nav2 .so 의 실제 경로·시각과 Nav2 가 로드한 라이브러리 확인
H=${JETSON_HOST:-192.168.0.101}; O="-o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null -o LogLevel=ERROR -o ConnectTimeout=10"
timeout 40 sshpass -p <PW> ssh $O jetson@$H 'find /home/jetson/ros2_ws/build/nvblox_nav2 /home/jetson/ros2_ws/install/nvblox_nav2 -name "*.so*" -printf "%TH:%TM:%TS %p\n" 2>/dev/null | cut -c1-120; echo "== planner 가 연 nvblox .so"; P=$(pgrep -f planner_server | head -1); grep -a nvblox /proc/$P/maps 2>/dev/null | awk "{print \$6}" | sort -u | head -3; echo "== 로컬 plugins: $(source /opt/ros/humble/setup.bash; source /home/jetson/ros2_ws/install/setup.bash; export FASTRTPS_DEFAULT_PROFILES_FILE=/home/jetson/ros2_ws/install/rover_bringup/share/rover_bringup/config/fastdds_udp_only.xml; timeout 12 ros2 param get /local_costmap/local_costmap plugins 2>&1 | tail -1 | cut -c1-90)"; echo "== nvblox 노드: $(docker exec isaac_ros_dev-aarch64-container pgrep -fc nvblox_node 2>/dev/null || echo 0)"'
